    ey = me.y - enemy.y
    edist = hypot(ex, ey)
    if edist < 0.05:
        edist = 0.05
    ehx = cos(radians(enemy.heading))
    ehy = sin(radians(enemy.heading))
    cosang = (ex * ehx + ey * ehy) / edist
    facing = cosang > 0.3
    hl = radians(enemy.heading + 90.0)
    lx = cos(hl)
    ly = sin(hl)
    lat = ex * lx + ey * ly
    r = hypot(me.x, me.y)
