        lxp = enemy.x + 1.0 * cos(hl)
        lyp = enemy.y + 1.0 * sin(hl)
        rxp = enemy.x + 1.0 * cos(hr)
        ryp = enemy.y + 1.0 * sin(hr)
        if hypot(lxp, lyp) < hypot(rxp, ryp):
            tx = lxp
            ty = lyp
        else:
            tx = rxp
            ty = ryp
        return steer(bearing_to(tx, ty))
    bias = min(1.2, 0.5 * max(0.0, dist - 1.2))
    px = -dy / dist
    py = dx / dist
    tx = enemy.x + px * bias
    ty = enemy.y + py * bias
    return steer(bearing_to(tx, ty))

